"""results/runs/*.json -> results/RESULTS.md and results/growth.png. Do not edit RESULTS.md by hand.

    python -m raga.report
"""
from __future__ import annotations

import json
from collections import defaultdict

import numpy as np
import pandas as pd

from . import metrics
from .data import ROOT

RESULTS = ROOT / "results"
ORDER = ["raga", "raga_unlevered", "hrp", "equal_weight", "sixty_forty", "nifty_buy_hold"]
LABELS = {
    "raga": "RAGA (as designed: GA + HRP, regime veto, 0.8-1.2x leverage)",
    "raga_unlevered": "RAGA weights, no leverage",
    "hrp": "HRP",
    "equal_weight": "Equal weight (within the same caps)",
    "sixty_forty": "60/40 (equity ETFs / bonds)",
    "nifty_buy_hold": "NIFTY 50 ETF, buy and hold",
}
SPLIT = "2021-12-31"


def load() -> dict[str, list[dict]]:
    runs = defaultdict(list)
    for path in sorted((RESULTS / "runs").glob("*.json")):
        run = json.loads(path.read_text(encoding="utf-8"))
        run["series"] = pd.Series(run["returns"], index=pd.to_datetime(run["dates"]))
        runs[run["strategy"]].append(run)
    return {name: sorted(runs[name], key=lambda r: (r["seed"] is None, r["seed"])) for name in ORDER if name in runs}


def _fmt(values, pct: bool, digits: int = 2) -> str:
    v = np.asarray(values, float) * (100 if pct else 1)
    unit = "%" if pct else ""
    if len(v) == 1:
        return f"{v[0]:.{digits}f}{unit}"
    return f"{v.mean():.{digits}f}{unit} ± {v.std(ddof=1):.{digits}f}"


def render(runs: dict[str, list[dict]]) -> str:
    first = next(iter(runs.values()))[0]
    d = first["data"]
    lines = [
        "# Results", "",
        "Generated by `python -m raga.report` from `results/runs/*.json`. Do not edit by hand.", "",
        f"Daily net returns in rupees from {d['first_return']} to {d['end']} ({d['days']:,} weekdays), after "
        f"{first['config']['COST_BPS']:g} bps of traded value per trade, with cash borrowed or lent at "
        f"{first['config']['CASH_RATE']:.0%} a year. Sharpe ratios are in excess of that rate. Every strategy "
        "rebalances every 21 weekdays from the same two-year training window and within the same caps (20% per asset; "
        "crypto 5%, commodities 15%, bonds 50%), except the NIFTY ETF, which is bought once. RAGA rows are mean ± "
        "sample standard deviation over GA seeds.", "",
        "| Strategy | Seeds | CAGR | Volatility | Sharpe | Max drawdown | Turnover per year |",
        "|---|---|---|---|---|---|---|",
    ]
    for name, rs in runs.items():
        m = [r["metrics"] for r in rs]
        lines.append(f"| {LABELS[name]} | {len(rs) if rs[0]['seed'] is not None else '–'} "
                     f"| {_fmt([x['cagr'] for x in m], True, 1)} | {_fmt([x['volatility'] for x in m], True, 1)} "
                     f"| {_fmt([x['sharpe'] for x in m], False)} | {_fmt([x['max_drawdown'] for x in m], True, 1)} "
                     f"| {_fmt([x['turnover_per_year'] for x in m], False, 1)}x |")

    lines += ["", f"## Sharpe by period (split at {SPLIT})", "",
              "| Strategy | First period | Second period |", "|---|---|---|"]
    for name, rs in runs.items():
        early = [metrics.sharpe(r["series"][:SPLIT]) for r in rs]
        late = [metrics.sharpe(r["series"][SPLIT:].iloc[1:]) for r in rs]
        lines.append(f"| {LABELS[name]} | {_fmt(early, False)} | {_fmt(late, False)} |")
    e = runs[next(iter(runs))][0]["series"]
    lines += ["", f"First period {e.index[0].date()} to {SPLIT}; second period to {e.index[-1].date()}."]

    if "raga" in runs:
        lines += ["", "## Is RAGA better than its baselines?", "",
                  "Sharpe difference on the same days, with a 95% moving-block bootstrap interval (21-day blocks, "
                  "2,000 resamples), one row per GA seed.", "",
                  "| Seed | RAGA − HRP | RAGA − equal weight | RAGA − NIFTY ETF |", "|---|---|---|---|"]
        for r in runs["raga"]:
            cells = []
            for other in ("hrp", "equal_weight", "nifty_buy_hold"):
                b = runs[other][0]["series"]
                diff, lo, hi = metrics.block_bootstrap_sharpe_diff(r["series"].to_numpy(), b.reindex(r["series"].index).to_numpy())
                cells.append(f"{diff:+.2f} [{lo:+.2f}, {hi:+.2f}]")
            lines.append(f"| {r['seed']} | " + " | ".join(cells) + " |")
        rs = runs["raga"]
        lines += ["", f"RAGA spent {_fmt([r['bad_regime_share'] for r in rs], True, 0)} of its {rs[0]['rebalances']} "
                  f"rebalances in the volatility veto (HRP only, 0.8x), at a mean leverage of "
                  f"{_fmt([r['mean_leverage'] for r in rs], False)}x. A GA backtest takes "
                  f"{_fmt([r['seconds'] / 60 for r in rs], False, 1)} minutes on a laptop CPU."]

    commits = sorted({r["commit"] for rs in runs.values() for r in rs})
    lines += ["", f"Prices: Yahoo Finance adjusted closes, {d['start']} to {d['end']}, sha256 `{d['sha256'][:16]}…`. "
              f"Runs produced by commit {', '.join(commits)}.", ""]
    return "\n".join(lines)


def figure(runs: dict[str, list[dict]]) -> None:
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    colors = {"raga": "#2a78d6", "raga_unlevered": "#7fb0e8", "hrp": "#1f9e77", "equal_weight": "#e08b2c",
              "sixty_forty": "#8a6fc9", "nifty_buy_hold": "#c0392b"}
    fig, ax = plt.subplots(figsize=(10, 5), dpi=130)
    for name, rs in runs.items():
        for k, r in enumerate(rs):
            wealth = (1 + r["series"]).cumprod()
            ax.plot(wealth.index, wealth.values, color=colors[name], linewidth=1.6 if k == 0 else 0.6,
                    alpha=1.0 if k == 0 else 0.5, label=LABELS[name] if k == 0 else None)
    ax.set_yscale("log")
    ax.set_ylabel("growth of ₹1 (log scale)")
    ax.set_title("Net of costs, in rupees; thin lines are other GA seeds", fontsize=10, loc="left")
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    ax.yaxis.grid(True, color="#e1e0d9", linewidth=1)
    ax.legend(frameon=False, fontsize=8, loc="upper left")
    fig.tight_layout()
    fig.savefig(RESULTS / "growth.png", bbox_inches="tight")
    plt.close(fig)


def main() -> None:
    runs = load()
    if not runs:
        raise SystemExit("no results/runs/*.json; run python -m raga.run first")
    (RESULTS / "RESULTS.md").write_text(render(runs), encoding="utf-8", newline="\n")
    figure(runs)
    print("wrote results/RESULTS.md and results/growth.png")


if __name__ == "__main__":
    main()
